import flask
from flask import request, jsonify, g
import sqlite3
import os
import hashlib
import hmac
import time

app = flask.Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session_token(token):
    """Verify HMAC-based session token: base64(user_id:timestamp:hmac)"""
    try:
        parts = token.split(':')
        if len(parts) != 3:
            return None
        user_id, ts, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), f"{user_id}:{ts}".encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(sig, expected):
            if time.time() - float(ts) < 86400:
                return user_id
    except Exception:
        pass
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by name - supports partial matching"""
    auth = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(auth)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    query = request.args.get('q', '')
    if not query or len(query) < 2:
        return jsonify({'error': 'query too short'}), 400

    # Sanitize: remove semicolons and comments to prevent multi-statement injection
    sanitized = query.replace(';', '').replace('--', '').replace('/*', '')

    db = get_db()
    # Build search query with LIKE for partial matching
    sql = f"SELECT id, username, email, role FROM users WHERE username LIKE '%{sanitized}%' OR email LIKE '%{sanitized}%'"

    try:
        results = db.execute(sql).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        app.logger.warning(f"DB error for query '{sanitized}': {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/users/<int:user_id>/profile', methods=['GET'])
def get_profile(user_id):
    """Get user profile - only own profile or admin"""
    auth = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(auth)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    row = db.execute('SELECT id, username, email, role, created_at FROM users WHERE id = ?', (user_id,)).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404

    # Authorization check
    if str(caller) != str(user_id):
        caller_row = db.execute('SELECT role FROM users WHERE id = ?', (caller,)).fetchone()
        if not caller_row or caller_row['role'] != 'admin':
            return jsonify({'error': 'forbidden'}), 403

    return jsonify(dict(row))

@app.route('/api/admin/export', methods=['POST'])
def export_data():
    """Admin-only data export endpoint"""
    auth = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(auth)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    caller_row = db.execute('SELECT role FROM users WHERE id = ?', (caller,)).fetchone()
    if not caller_row or caller_row['role'] != 'admin':
        return jsonify({'error': 'admin required'}), 403

    table = request.json.get('table', 'users')
    # Whitelist tables
    allowed = ['users', 'audit_log', 'sessions']
    if table not in allowed:
        return jsonify({'error': 'invalid table'}), 400

    rows = db.execute(f'SELECT * FROM {table}').fetchall()
    return jsonify({'data': [dict(r) for r in rows], 'table': table})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
